story=[]
def clean(t):
 t=str(t)
 t=t.replace('Pure stocks','Active stocks').replace('pure stocks','active stocks')
 t=re.sub(r'\bPure\b','Active',t);t=re.sub(r'\bpure\b','active',t)
 # Protect HTML entities from the punctuation-spacing pass.
 entities={}
 def stash(m):
  key=f"ENTITYTOKEN{len(entities)}END";entities[key]=m.group(0);return key
 t=re.sub(r"&(?:[A-Za-z][A-Za-z0-9]*|#[0-9]+|#x[0-9A-Fa-f]+);",stash,t)
 t=re.sub(r'\b(March|May|June|November|December|September|October|February)(?=\d)',r'\1 ',t)
 t=re.sub(r'\b(all|across|difference|x)(?=\d)',r'\1 ',t)
 t=re.sub(r',(?=[A-Za-z])',', ',t);t=re.sub(r';(?=[A-Za-z0-9])','; ',t)
 t=re.sub(r':(?=[A-Za-z0-9])',': ',t)
 for key,value in entities.items():t=t.replace(key,value)
 return t
def add(t,style='Body'):story.append(Paragraph(clean(t) if style!='CodeX' else t,styles[style]))
def table(rows,widths):
 t=Table([[Paragraph(clean(c),styles['Small']) for c in r] for r in rows],colWidths=widths,hAlign='LEFT',repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8f0f5')),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),('LINEBELOW',(0,0),(-1,-1),.3,colors.HexColor('#c5d1db'))]));story.append(t);story.append(Spacer(1,5))
